    "starterCode": "#include <iostream>\n#include <deque>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, k; cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) cin >> nums[i];\n    // TODO: sliding window max\n    return 0;\n}",
    "solution": "#include <iostream>\n#include <deque>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, k; cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) cin >> nums[i];\n    deque<int> dq;\n    bool first = true;\n    for (int i = 0; i < n; i++) {\n        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();\n        while (!dq.empty() && nums[dq.back()] <= nums[i]) dq.pop_back();\n        dq.push_back(i);\n        if (i >= k - 1) {\n            if (!first) cout << \" \";\n            cout << nums[dq.front()];\n            first = false;\n        }\n    }\n    cout << endl;\n    return 0;\n}",
