    "solution": "#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node* next;\n    Node(int v) : val(v), next(nullptr) {}\n};\n\nNode* buildList(int n) {\n    Node* head = nullptr, *tail = nullptr;\n    for (int i = 0; i < n; i++) {\n        int v; cin >> v;\n        Node* nd = new Node(v);\n        if (!head) head = tail = nd;\n        else { tail->next = nd; tail = nd; }\n    }\n    return head;\n}\n\nNode* mergeLists(Node* l1, Node* l2) {\n    Node dummy(0);\n    Node* tail = &dummy;\n    while (l1 && l2) {\n        if (l1->val <= l2->val) { tail->next = l1; l1 = l1->next; }\n        else { tail->next = l2; l2 = l2->next; }\n        tail = tail->next;\n    }\n    tail->next = l1 ? l1 : l2;\n    return dummy.next;\n}\n\nint main() {\n    int n; cin >> n;\n    Node* l1 = buildList(n);\n    int m; cin >> m;\n    Node* l2 = buildList(m);\n    Node* merged = mergeLists(l1, l2);\n    Node* c = merged;\n    while (c) { cout << c->val << \" -> \"; c = c->next; }\n    cout << \"NULL\" << endl;\n    return 0;\n}",
