    "solution": "#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node *left, *right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* insert(Node* root, int val) {\n    if (!root) return new Node(val);\n    if (val < root->val) root->left = insert(root->left, val);\n    else root->right = insert(root->right, val);\n    return root;\n}\n\nbool first_print = true;\nvoid inorder(Node* root) {\n    if (!root) return;\n    inorder(root->left);\n    if (!first_print) cout << \" \";\n    cout << root->val;\n    first_print = false;\n    inorder(root->right);\n}\n\nint main() {\n    int n; cin >> n;\n    Node* root = nullptr;\n    for (int i = 0; i < n; i++) {\n        int v; cin >> v;\n        root = insert(root, v);\n    }\n    inorder(root);\n    cout << endl;\n    return 0;\n}",
