    "starterCode": "#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node *left, *right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* insert(Node* r, int v) {\n    if (!r) return new Node(v);\n    if (v < r->val) r->left = insert(r->left, v);\n    else r->right = insert(r->right, v);\n    return r;\n}\n\n// TODO: bool search(Node* r, int v)\n\nint main() {\n    int n; cin >> n;\n    Node* root = nullptr;\n    for (int i = 0; i < n; i++) { int v; cin >> v; root = insert(root, v); }\n    int q; cin >> q;\n    while (q--) {\n        int v; cin >> v;\n        cout << (search(root, v) ? \"Found\" : \"Not found\") << endl;\n    }\n    return 0;\n}",
    "solution": "#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int val;\n    Node *left, *right;\n    Node(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nNode* insert(Node* r, int v) {\n    if (!r) return new Node(v);\n    if (v < r->val) r->left = insert(r->left, v);\n    else r->right = insert(r->right, v);\n    return r;\n}\n\nbool search(Node* r, int v) {\n    if (!r) return false;\n    if (r->val == v) return true;\n    if (v < r->val) return search(r->left, v);\n    return search(r->right, v);\n}\n\nint main() {\n    int n; cin >> n;\n    Node* root = nullptr;\n    for (int i = 0; i < n; i++) { int v; cin >> v; root = insert(root, v); }\n    int q; cin >> q;\n    while (q--) {\n        int v; cin >> v;\n        cout << (search(root, v) ? \"Found\" : \"Not found\") << endl;\n    }\n    return 0;\n}",
