    "starterCode": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <climits>\nusing namespace std;\n\nint main() {\n    int n, m; cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n);\n    // TODO: Dijkstra\n    return 0;\n}",
    "solution": "#include <iostream>\n#include <vector>\n#include <queue>\n#include <climits>\nusing namespace std;\n\nint main() {\n    int n, m; cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n);\n    for (int i = 0; i < m; i++) {\n        int u, v, w; cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n    }\n    vector<long long> dist(n, LLONG_MAX);\n    priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;\n    dist[0] = 0;\n    pq.push({0, 0});\n    while (!pq.empty()) {\n        auto [d, u] = pq.top(); pq.pop();\n        if (d > dist[u]) continue;\n        for (auto [v, w] : adj[u]) {\n            if (dist[u] + w < dist[v]) {\n                dist[v] = dist[u] + w;\n                pq.push({dist[v], v});\n            }\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (i) cout << \" \";\n        cout << (dist[i] == LLONG_MAX ? -1 : dist[i]);\n    }\n    cout << endl;\n    return 0;\n}",
