    "solution": "#include <iostream>\n#include <vector>\n#include <stack>\nusing namespace std;\n\nint main() {\n    int n; cin >> n;\n    vector<int> nums(n), res(n, -1);\n    for (int i = 0; i < n; i++) cin >> nums[i];\n    stack<int> st;\n    for (int i = 0; i < n; i++) {\n        while (!st.empty() && nums[st.top()] < nums[i]) {\n            res[st.top()] = nums[i];\n            st.pop();\n        }\n        st.push(i);\n    }\n    for (int i = 0; i < n; i++) {\n        if (i) cout << \" \";\n        cout << res[i];\n    }\n    cout << endl;\n    return 0;\n}",
